def transform(grid):
    h, w = len(grid), len(grid[0])
    refs = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(x == row[0] for x in row)]
    if not refs:
        return [row[:] for row in grid]

    # The solid rows are samples of a repeating horizontal stripe sequence.
    # Use the shortest period that assigns each sampled row a consistent phase.
    period = next((p for p in range(1, h + 1)
                   if all((r1 - r2) % p != 0 or a == b
                          for i, (r1, a) in enumerate(refs)
                          for r2, b in refs[i + 1:])), h)
    phases = {}
    for r, color in refs:
        phases[r % period] = color
    # For these stripe puzzles the clues determine each phase; for any missing
    # phase, carry forward the closest preceding sampled phase cyclically.
    known = sorted(phases)
    for phase in range(period):
        if phase not in phases:
            prev = min(known, key=lambda q: (phase - q) % period)
            phases[phase] = phases[prev]
    return [[phases[r % period]] * w for r in range(h)]

