def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c, v) for r, row in enumerate(grid)
           for c, v in enumerate(row) if v]
    if not pts:
        return [row[:] for row in grid]

    # Colored marks lie on parallel stripes: horizontal, vertical, or either
    # diagonal orientation. Choose the orientation that best groups equal marks.
    keys = {
        'row': lambda r, c: r,
        'col': lambda r, c: c,
        'sum': lambda r, c: r + c,
        'diff': lambda r, c: c - r,
    }
    def score(fn):
        groups = {}
        for r, c, v in pts:
            groups.setdefault(fn(r, c), []).append(v)
        return sum(len(a) ** 2 for a in groups.values()
                   if len(a) > 1 and len(set(a)) == 1) - \
               sum(len(a) ** 2 for a in groups.values()
                   if len(set(a)) > 1)
    orient = max(keys, key=lambda k: score(keys[k]))
    fn = keys[orient]
    samples = [(fn(r, c), v) for r, c, v in pts]

    # For horizontal/vertical full stripes, use the shortest consistent period;
    # fill unobserved stripes with the dominant stripe color.
    maxperiod = max(h, w)
    period = next(p for p in range(1, maxperiod + 1)
                  if all((a-b) % p != 0 or x == y
                         for i, (a, x) in enumerate(samples)
                         for b, y in samples[i+1:]))
    phase = {a % period: v for a, v in samples}
    missing_fill = Counter(v for _, v in samples).most_common(1)[0][0]
    for q in range(period):
        phase.setdefault(q, missing_fill)

    if orient == 'row':
        return [[phase[r % period]] * w for r in range(h)]
    if orient == 'col':
        return [[phase[c % period] for c in range(w)] for _ in range(h)]
    if orient == 'sum':
        return [[phase[(r+c) % period] for c in range(w)] for r in range(h)]
    return [[phase[(c-r) % period] for c in range(w)] for r in range(h)]
